async function save(c,url){
  try{
    const pp=new URL(url,location.href).pathname;if(isShared(pp))c=await caches.open(FILES);
    const res=await fetch(url,{cache:'no-cache'});
    if(!res.ok)return false;
    const r=await clean(res);
    await c.put(url,r.clone());
    const p=new URL(url,location.href).pathname;
    if(p.endsWith('.html'))await c.put(p.slice(0,-5),r.clone());          // /map1
    if(p.endsWith('/index.html'))await c.put(p.slice(0,-10),r.clone());    // /ws1/
    return true;
  }catch(e){return false}
}
let filling=null,lastNav=0;
async function fill(){
  if(filling)return filling;
  filling=(async()=>{
    const c=await caches.open(CACHE),f=await caches.open(FILES);
    const have=new Set((await c.keys()).concat(await f.keys()).map(r=>new URL(r.url).pathname));
    const todo=ALL.filter(u=>!have.has(u)); // ALL is already ordered: pages, small files, pictures and sounds by size, videos last
    // remove old pictures no longer used by the site
    const keep=new Set(ALL);for(const r of await f.keys()){const p=new URL(r.url).pathname;if(!keep.has(p))f.delete(r)}
    await new Promise(r=>setTimeout(r,8000)); // let the open page load first
    let i=0;
    // one file at a time, and step aside whenever the child opens a page, so the download never slows the app down
    const nap=ms=>new Promise(r=>setTimeout(r,ms));
    while(i<todo.length){
      while(Date.now()-lastNav<5000)await nap(1000);
      await save(c,todo[i++]);await nap(150);
    }
    filling=null;
    const left=ALL.filter(u=>!have.has(u)).length;
    report();
  })();
  return filling;
}
async function status(){
  const c=await caches.open(CACHE),f=await caches.open(FILES);
  const have=new Set((await c.keys()).concat(await f.keys()).map(r=>new URL(r.url).pathname));
  const done=ALL.filter(u=>have.has(u)).length;
  return {done,total:ALL.length};
}
async function report(){
  const s=await status();
  const cl=await self.clients.matchAll({includeUncontrolled:true});
  cl.forEach(x=>x.postMessage({type:'offline-status',...s}));
}
self.addEventListener('install',e=>{
  self.skipWaiting();
  e.waitUntil(caches.open(CACHE).then(c=>Promise.all(CORE.map(u=>save(c,u)))));
});
self.addEventListener('activate',e=>{
  e.waitUntil(caches.keys().then(ks=>Promise.all(ks.filter(k=>k!==CACHE&&k!==FONTS&&k!==FILES).map(k=>caches.delete(k))))
    .then(()=>self.clients.claim()).then(()=>{fill()}));
});
self.addEventListener('message',e=>{
  if(e.data==='fill')e.waitUntil(fill());
  if(e.data==='status')e.waitUntil(report());
});

// video: answer "range" requests from the saved full file
async function video(req){
  const url=new URL(req.url);url.search='';
  const c=await caches.open(CACHE);
  let hit=await c.match(url.pathname);
  if(!hit){
    // not saved yet: play straight from the internet (fast start) (it is saved later with the rest of the site)
    try{return await fetch(req)}catch(e){return new Response('',{status:504})}
  }
  const buf=await hit.arrayBuffer();
  const type=hit.headers.get('content-type')||'video/mp4';
  const range=req.headers.get('range');
  if(!range)return new Response(buf,{status:200,headers:{'Content-Type':type,'Content-Length':buf.byteLength,'Accept-Ranges':'bytes'}});
  const m=/bytes=(\d*)-(\d*)/.exec(range)||[];
  let start=m[1]?parseInt(m[1]):0,end=m[2]?parseInt(m[2]):buf.byteLength-1;
  if(!m[1]&&m[2]){start=buf.byteLength-parseInt(m[2]);end=buf.byteLength-1}
  end=Math.min(end,buf.byteLength-1);
  return new Response(buf.slice(start,end+1),{status:206,statusText:'Partial Content',headers:{
    'Content-Type':type,'Content-Length':end-start+1,'Content-Range':`bytes ${start}-${end}/${buf.byteLength}`,'Accept-Ranges':'bytes'}});
}
// pages: try the internet for 4 seconds, otherwise the saved copy
async function page(req){
  lastNav=Date.now();
  const c=await caches.open(CACHE);
  const p=new URL(req.url).pathname;
  const saved=await c.match(req,{ignoreSearch:true})||await c.match(p,{ignoreSearch:true})||
              await c.match(p.endsWith('.html')?p.slice(0,-5):p+'.html')||
              await c.match(p.endsWith('/')?p+'index.html':p+'/index.html');
  const net=fetch(req).then(async res=>{if(res.ok){const r=await clean(res);c.put(req,r.clone());return r}return res});
  // a saved copy opens at once; the fresh copy is fetched quietly for next time
  if(saved){net.catch(()=>{});return saved}
  try{const r=await net;if(r)return r}catch(e){}
  return (await c.match('/index.html'))||Response.error();
}
// pictures, sounds and other files: saved copy first
async function file(req){
  const c=await cacheFor(new URL(req.url).pathname);
  const hit=await c.match(req,{ignoreSearch:true})||await caches.match(req,{ignoreSearch:true});
  if(hit)return hit;
  const res=await fetch(req);
  if(res.ok){const r=await clean(res);c.put(req,r.clone());return r}
  return res;
}
async function font(req){
  const c=await caches.open(FONTS);
  const hit=await c.match(req);
  if(hit)return hit;
  try{const res=await fetch(req);if(res.ok||res.type==='opaque')c.put(req,res.clone());return res}
  catch(e){return new Response('',{status:504})}
}
self.addEventListener('fetch',e=>{
  const r=e.request;if(r.method!=='GET')return;
  const u=new URL(r.url);
  if(/fonts\.(googleapis|gstatic)\.com$/.test(u.hostname)){e.respondWith(font(r));return}
  if(!sameOrigin(r.url))return;
  if(/\.(mp4|webm)$/.test(u.pathname)){e.respondWith(video(r));return}
  if(r.mode==='navigate'||/\.html$/.test(u.pathname)||u.pathname.endsWith('/')){e.respondWith(page(r));return}
  e.respondWith(file(r));
});
